// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 v) public {
        v = bound(v, 0, 1e30);
        // owner of c is this test contract (msg.sender at deployment).
        // Fund the contract with exactly v wei.
        vm.deal(address(c), v);
        uint256 before = address(c).balance;
        c.withdraw(v);
        // General rule: withdrawing v from the owner must move exactly v wei
        // out of the contract.
        assertEq(before - address(c).balance, v);
    }
}
